def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: datetime.timedelta
    :return: dict representation with days, seconds, microseconds
    """
    if value is None:
        return None
    try:
        from datetime import timedelta
    except Exception as exc:
        raise RuntimeError("datetime module unavailable") from exc
    if not isinstance(value, timedelta):
        raise TypeError(f"Expected datetime.timedelta, got {type(value).__name__}")
    # Extract components in a serialisable form
    return {
        "days": value.days,
        "seconds": value.seconds,
        "microseconds": value.microseconds
    }

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None

    # Try using datetime.time.isoformat() for consistency with ISO 8601.
    try:
        return value.isoformat()
    except AttributeError:
        # If value does not support isoformat, try common attributes.
        try:
            hour = getattr(value, "hour")
            minute = getattr(value, "minute")
            second = getattr(value, "second", 0)
            microsecond = getattr(value, "microsecond", 0)
            if microsecond:
                return f"{hour:02d}:{minute:02d}:{second:02d}.{microsecond:06d}"
            else:
                return f"{hour:02d}:{minute:02d}:{second:02d}"
        except Exception as exc:
            raise TypeError("Cannot dehydrate value to time string: %r" % value) from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: a JSON‑serialisable representation of the point
    """
    # None is allowed
    if value is None:
        return None

    # Handle dictionary-like objects
    if isinstance(value, dict):
        if 'x' in value and 'y' in value:
            return {'x': value['x'], 'y': value['y']}
        # Return as-is if it already looks like a point dictionary
        return value

    # Handle sequences (tuples / lists)
    if isinstance(value, (tuple, list)):
        if len(value) >= 2:
            # return the first two coordinates
            return tuple(value[:2]) if isinstance(value, tuple) else list(value[:2])
        # Too short – return as‑is
        return value

    # Handle objects with x, y attributes (e.g., a simple Point class)
    if hasattr(value, 'x') and hasattr(value, 'y'):
        try:
            return {'x': getattr(value, 'x'), 'y': getattr(value, 'y')}
        except Exception:
            pass

    # Handle objects with a coordinates attribute (e.g., shapely, numpy)
    if hasattr(value, 'coordinates'):
        try:
            coord = getattr(value, 'coordinates')
            if isinstance(coord, (tuple, list)):
                if len(coord) >= 2:
                    return tuple(coord[:2]) if isinstance(coord, tuple) else list(coord[:2])
        except Exception:
            pass

    # Fallback: try to convert to string
    try:
        return str(value)
    except Exception:
        # If all else fails, return None
        return None

def keys(self):
    """Return the keys of the record.

    :return: List of key names
    """
    try:
        # Prefer a dedicated data attribute, if it exists
        record = getattr(self, "_data", None)
        if record is None:
            record = getattr(self, "data", None)
        # If the instance itself is a mapping
        if record is None and isinstance(self, dict):
            record = self
        # Fallback to the instance's own attributes
        if record is None:
            record = vars(self)
        # Ensure we can perform .keys()
        if not hasattr(record, "keys"):
            raise TypeError(f"Object {self!r} does not provide keys")
        return list(record.keys())
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve keys from {self!r}") from exc

def protocol_handlers(cls, protocol_version=None):
        """Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the mapping of protocol handlers defined on the class.
        # If the class does not define it, assume no handlers available.
        handlers = getattr(cls, "_protocol_handlers", {})
        if not isinstance(handlers, dict):
            # Fall back to an empty mapping if the attribute exists but is not a dict
            handlers = {}

        # Validate the protocol_version argument if supplied
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Return all handlers if no specific version is requested
        if protocol_version is None:
            # Return a copy to prevent accidental mutation
            return dict(handlers)

        # Return a single entry if the requested version is supported, else an empty dict
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

def index(self, key):
