def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Try to obtain the underlying data structure
    try:
        data = self._data
    except AttributeError:
        # Fallback to dict-like or iterable of pairs
        if hasattr(self, 'items'):
            data = dict(self.items())
        else:
            try:
                data = dict(self)
            except Exception:
                data = {}

    values_list = list(data.values())

    if not keys:
        return values_list

    result = []
    for key in keys:
        if isinstance(key, int):
            # Index filtering
            if 0 <= key < len(values_list):
                result.append(values_list[key])
            else:
                # Index out of bounds, append None (or could raise)
                result.append(None)
        else:
            # Key filtering
            if key in data:
                result.append(data[key])
            else:
                # Missing key, append None (or could raise)
                result.append(None)
    return result

def deprecated(message):
    """Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("parse_version expects a string")
    import re
    parts = re.split(r'\D+', s.strip())
    nums = [int(p) for p in parts if p]
    return tuple(nums)

