                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    def decorating_function(user_function):
        cache = {}
        hits = misses = 0
        from functools import wraps

        @wraps(user_function)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            # Build a hashable key from arguments
            key = args
            if kwargs:
                try:
                    items = tuple(sorted(kwargs.items()))
                    key += items
                except TypeError:
                    # Unhashable keyword arguments can't be cached
                    return user_function(*args, **kwargs)
            if typed:
                try:
                    type_key = tuple(type(v) for v in args)
                    if kwargs:
                        type_key += tuple(type(v) for _, v in sorted(kwargs.items()))
                    key += type_key
                except Exception:
                    # If types can't be used as part of key, skip caching
                    return user_function(*args, **kwargs)
            try:
                result = cache[key]
                hits += 1
                # Move key to end to mark it as recently used
                cache.move_to_end(key)
            except KeyError:
                result = user_function(*args, **kwargs)
                cache[key] = result
                misses += 1
                if len(cache) > maxsize:
                    # Pop the least recently used item
                    cache.popitem(last=False)
            return result

        def cache_info():
            """Return a tuple of hits, misses, current size and maxsize."""
            return hits, misses, len(cache), maxsize

        def cache_clear():
            """Clear the cache and reset statistics."""
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper
    return decorating_function

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError("The dictionary is empty")
    # Retrieve the value and remove the key
    try:
        # Prefer the built‑in pop method if available
        value = self.pop(first_key)
    except AttributeError:
        # Fallback to manual deletion
        value = self[first_key]
        del self[first_key]
    return first_key, value

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
    """ D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    if key in self:
        return self[key]
    return default

