    """
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Compute the cache key from the argument values
            try:
                k = key(args, kwargs)
            except Exception as exc:
                raise ValueError(f"Error computing cache key: {exc}") from exc

            # Use the lock if provided for thread‑safety
            if lock:
                with lock:
