def file_to_textbuffer(file_name, encoding):
        """Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype str
        """
        if not isinstance(file_name, str):
            raise TypeError("file_name must be a string")
        if not isinstance(encoding, str):
            raise TypeError("encoding must be a string")
        try:
            with open(file_name, "r", encoding=encoding) as f:
                return f.read()
        except Exception:
            return None

def _reset_logging(cls):
    """Reset logging configuration to defaults."""
    import logging
    try:
        root = logging.getLogger()
        # Remove all handlers attached to the root logger
        while root.handlers:
            handler = root.handlers[0]
            root.removeHandler(handler)
            # Attempt to close the handler to release resources
            try:
                handler.close()
            except Exception:
                pass
        # Restore the root logger to a sane default state
        root.setLevel(logging.WARNING)
        root.propagate = True
    except Exception:
        # Ignore any errors (e.g. logging module not available)
        pass

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Get the interface definition defined on the class
    interface = getattr(self.__class__, "INTERFACE", {})
    result = {}
    for name, meta in interface.items():
        # Support either a dict with a 'description' entry or a tuple/list
        if isinstance(meta, dict):
            desc = meta.get("description", "")
        elif isinstance(meta, (list, tuple)) and len(meta) > 1:
            desc = meta[1]
        else:
            desc = ""
        result[name] = desc
    if all:
        # Include any attributes present on the instance that aren't part of the interface
        for attr in vars(self):
            if attr not in result:
                result[attr] = ""
    return result

