def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate type of argument
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Ensure the object has the expected dictionary of error indices
    if not hasattr(self, "_err_indices"):
        raise AttributeError("Missing '_err_indices' attribute on the instance.")

    # Attempt to fetch the indices for the requested coordinate
    indices = self._err_indices.get(coord_name)
    if indices is None:
        raise KeyError(f"No errors registered for coordinate '{coord_name}'.")

    # Ensure we return a mutable but non‑directly editable sequence
    try:
        # If indices is already a list/tuple, cast to list; otherwise, try to iterate
        return list(indices)
    except TypeError:
        # In case indices is not iterable (unlikely), wrap it in a list
        return [indices]

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs
    if not isinstance(bins, (list, tuple)):
        raise TypeError("`bins` must be a list or tuple.")
    if not isinstance(edges, (list, tuple)):
        raise TypeError("`edges` must be a list or tuple.")
    if len(edges) - 1 != len(bins):
        raise ValueError(
            f"Number of edges ({len(edges)}) must be one more than number of bins ({len(bins)})."
        )
    if len(bins) == 0:
        return 0.0

    # Ensure edges are sorted non-decreasingly
    for i in range(len(edges) - 1):
        if edges[i] > edges[i + 1]:
            raise ValueError(
                f"Edges must be non-decreasing; edge[{i}] ({edges[i]}) > edge[{i+1}] ({edges[i+1]})."
            )

    total = 0.0
    for bin_val, left, right in zip(bins, edges, edges[1:]):
        try:
            w = float(right) - float(left)
            v = float(bin_val)
        except Exception as exc:
            raise TypeError(
                f"Bins and edges must be numeric. Problem with bin={bin_val}, left={left}, right={right}."
            ) from exc
        total += v * w
    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Import classes lazily to avoid circular imports or unnecessary overhead
    try:
        from fo_ilike_folia.elements import FillRequest, Source
    except Exception:
        # If the specific classes cannot be imported, we cannot perform the test reliably
        return False

    # If seq is a single element
    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, Source):
        return False

    # If seq is an iterable (but not a string/bytes)
    try:
        # Strings and bytes are iterable but should not be treated as sequences of elements
        if isinstance(seq, (str, bytes)):
            return False
        for item in seq:
            # If any item is a Source element, the sequence is invalid
            if isinstance(item, Source):
                return False
            if isinstance(item, FillRequest):
                return True
        # No FillRequest found
        return False
    except TypeError:
        # seq is not iterable
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    if obj is None:
        return False
    return (
        hasattr(obj, "fill") and callable(getattr(obj, "fill", None)) and
        hasattr(obj, "request") and callable(getattr(obj, "request", None))
    )

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run'))
    except (AttributeError, TypeError):
        return False
    except Exception:
        # If any other exception occurs, do not crash; simply indicate it is not a run element.
        return False

def is_fill_compute_el(obj):
