    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    def _diff(a, b, depth):
        res = {}
        for k, v in a.items():
            if k not in b:
                # Key not in second dict – include it
                res[k] = v
                continue

            v2 = b[k]
            # Check if both values are dicts and recursion allowed
            if isinstance(v, dict) and isinstance(v2, dict) and depth != 0:
                # Recurse into sub‑dictionary
                sub = _diff(v, v2, depth - 1 if depth > 0 else depth)
                if sub:
                    res[k] = sub
                continue

            # Non‑dict values or recursion blocked – compare directly
            if v != v2:
                res[k] = v

        return res

    return _diff(d1, d2, level) if level != 0 else {}

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    # Validate that `labels` is a mapping
    if not isinstance(labels, dict):
        raise ValidationError(f"labels must be a dict, got {type(labels).__name__}")

    errors = []

    # Helper to test a single string against a regex
    def _match_regex(value, regex, value_desc):
        """
        Returns None if value matches regex, otherwise an error message.
        `regex` is expected to be a compiled regular expression object.
        """
        try:
            # use fullmatch to ensure the whole string matches the pattern
            if not regex.fullmatch(value):
                return f"{value_desc} '{value}' does not match the regex [{regex.pattern}]"
        except Exception as exc:
            # In case the regex object is invalid or the match operation fails
            return f"Failed to validate {value_desc} '{value}': {exc}"
        return None

    # Iterate over keys and values in the label dictionary
    for key, val in labels.items():
        # Check key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            # Try to validate key against key regex (if defined)
            if 'LABEL_KEY_REGEX' in globals():
                err_msg = _match_regex(key, globals()['LABEL_KEY_REGEX'], "Label key")
                if err_msg:
                    errors.append({key: err_msg})

        # Validate value(s)
        # If the value is a sequence (list or tuple), validate each elem
        if isinstance(val, (list, tuple)):
            for item in val:
                if not isinstance(item, (str, bytes)):
                    errors.append({str(val): "expected string or bytes-like object"})
                else:
                    if 'LABEL_VALUE_REGEX' in globals():
                        err_msg = _match_regex(item, globals()['LABEL_VALUE_REGEX'], "Label value")
                        if err_msg:
                            errors.append({item: err_msg})
        else:
            if not isinstance(val, (str, bytes)):
                errors.append({str(val): "expected string or bytes-like object"})
            else:
                if 'LABEL_VALUE_REGEX' in globals():
                    err_msg = _match_regex(val, globals()['LABEL_VALUE_REGEX'], "Label value")
                    if err_msg:
                        errors.append({val: err_msg})

    # If any errors were collected, raise a ValidationError
    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # guard against missing attributes
    try:
        manifest = getattr(app.spec, "manifest", None)
        if manifest is None:
            return  # nothing to do
    except Exception:
        return

    # Ensure we have a dict to store observer schemas.  The actual key
    # where schemas are stored may vary; try a few common names.
    observer_dict = None
    for attr in ("observer_schemas", "observer_schema", "observerSchema",
                 "default_observer_schema", "defaultObserverSchema"):
        if hasattr(app.spec, attr):
            observer_dict = getattr(app.spec, attr)
            break
    if observer_dict is None:
        # If no such attribute exists, create one on the spec
        observer_dict = {}
        setattr(app.spec, "observer_schemas", observer_dict)

    # If the 'manifest' is a list/tuple of resource dicts, handle directly.
    # If it is a dict keyed by name, iterate over its values.
    if isinstance(manifest, (list, tuple, set)):
        resources = list(manifest)
    elif isinstance(manifest, dict):
        resources = list(manifest.values())
    else:
        # Unsupported type – do nothing
        resources = []

    for resource in resources:
        if not isinstance(resource, dict):
            continue

        kind = resource.get("kind")
        if not kind:
            continue

        # Skip if a custom observer schema already exists
        if kind in observer_dict and observer_dict[kind]:
            continue

        # Build a very simple default schema: copy the top-level keys
        # of the resource, treating everything as stringish.  In a real
        # implementation this would be more sophisticated.
        default_schema = {}
        for key, value in resource.items():
            if key == "metadata":
                # Keep the name and namespace
                meta = {}
                for meta_key in ("name", "namespace", "labels", "annotations"):
                    if meta_key in value:
                        meta[meta_key] = value[meta_key]
                default_schema["metadata"] = meta
            else:
                # Treat other fields generically
                default_schema[key] = type(value).__name__

        # Store the generated schema
        observer_dict[kind] = default_schema

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Import here to avoid top-level imports
        import os
        import json

        # Resolve the actual root path
        # If path has a 'root' attribute (e.g., pyfs root object), use it
        if hasattr(path, "root"):
            root_path = str(getattr(path, "root"))
        else:
            root_path = str(path)

        if not os.path.exists(root_path):
            return False

        # Assume the manifest JSON file is named 'manifest.json' at the root
        manifest_path = os.path.join(root_path, "manifest.json")
        if not os.path.isfile(manifest_path):
            return False

        # Load and parse the JSON manifest
        with open(manifest_path, "r", encoding="utf-8") as f:
            try:
                manifest = json.load(f)
            except json.JSONDecodeError:
                return False

        # Basic structural checks – these are minimal and can be extended
        required_keys = {"ocfl_version", "objects", "distributions"}
        if not required_keys.issubset(manifest):
            return False

        if not isinstance(manifest["objects"], list):
            return False
        if not isinstance(manifest["distributions"], dict):
            return False

        # All checks passed – consider it valid (warnings not raised here)
        return True
    except Exception:
        # Any unexpected error means validation failed
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if prefix is None:
        prefix = ''
    if not isinstance(prefix, str):
        raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
    try:
        status = getattr(self, 'status', None)
    except Exception:
        status = None
    if status is None or status == '':
        return prefix
    try:
        status_repr = str(status)
    except Exception:
        status_repr = repr(status)
    return f"{prefix}{status_repr}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Try to get the validation log from common attribute names
    logs = getattr(self, 'validation_log', None)
    if logs is None:
        logs = getattr(self, 'log', None)
    if not logs:
        return ''
    # Convert log entries to string and prepend prefix
    lines = []
    for entry in logs:
        try:
            line = str(entry)
        except Exception:
            line = '<unprintable entry>'
        lines.append(f"{prefix}{line}")
    return '\n'.join(lines)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digests")
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be an iterable of digests")

    # Coerce to sets for easy comparison
    manifest_digests = set()
    for value in manifest_files.values():
        # In case a file maps to multiple digests (e.g. list or set)
        if isinstance(value, (set, list, tuple)):
            manifest_digests.update(item for item in value if isinstance(item, str))
        elif isinstance(value, str):
            manifest_digests.add(value)
        else:
            raise ValueError(f"Unexpected digest type for file '{value}': {type(value)}")

    digests_used_set = set(digests_used)

    # Check for missing digests in the manifest
    missing = digests_used_set - manifest_digests
    if missing:
        raise ValueError(
            "The following digests are used but missing from the manifest: "
            + ", ".join(sorted(missing))
        )

    # Issue warning for digests present in the manifest but not used
    unused = manifest_digests - digests_used_set
    if unused:
        import warnings
        warnings.warn(
            "The following digests are present in the manifest but not used: "
            + ", ".join(sorted(unused)),
            RuntimeWarning,
        )

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to data")
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or integer")

    # Gather all versions in sorted order for later comparison
    try:
        sorted_versions = sorted(inventory.keys(), key=lambda v: int(v) if isinstance(v, (str, int)) and str(v).isdigit() else v)
    except Exception:
        # Fallback to simple sorting if conversion fails
        sorted_versions = sorted(inventory.keys())

    # Find starting index of the requested version
    try:
        start_index = sorted_versions.index(version)
    except ValueError:
        # Version not present; return empty mapping
        return {}

    # Helper to normalize content files into a set
    def to_set(val):
        if isinstance(val, (list, set, tuple)):
            return set(val)
        if isinstance(val, str):
            return {val}
        # If it's None or empty, return empty set
        if val is None:
            return set()
        # For any other type, try to wrap in a set
        try:
            return {val}
        except Exception:
            return set()

    result = {}

    # Iterate over all relevant logical paths for the requested version and later ones
    for v in sorted_versions[start_index:]:
        data_per_version = inventory.get(v, {})
        if not isinstance(data_per_version, dict):
            continue  # skip malformed entries
        for logic_path, content in data_per_version.items():
            if logic_path not in result:
                result[logic_path] = set()
            result[logic_path].update(to_set(content))

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dictionary")

    # Common structure: expected to have a top-level 'files' list
    if 'files' not in fixity:
        raise ValueError("The fixity block must contain a 'files' key")

    file_entries = fixity['files']
    if not isinstance(file_entries, list):
        raise TypeError("'files' in the fixity block must be a list")

    # Ensure the manifest_files collection is iterable and build a set for efficient look-up
    if manifest_files is None:
        raise ValueError("manifest_files argument cannot be None")
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise TypeError("manifest_files must be an iterable of filenames")

    seen = set()
    for entry in file_entries:
        if not isinstance(entry, dict):
            raise TypeError("Each item in 'files' must be a dictionary")

        if 'filename' not in entry or 'hash' not in entry:
            raise ValueError("Each file entry must contain 'filename' and 'hash' fields")

        filename = entry['filename']
        if not isinstance(filename, str):
            raise TypeError("'filename' must be a string")

        # Ensure the file is actually in the manifest
        if filename not in manifest_set:
            raise ValueError(f"Fixity references an unknown file: {filename}")

        # Optional: check that each file appears only once in the fixity block
        if filename in seen:
            raise ValueError(f"Duplicate file reference in fixity block: {filename}")
        seen.add(filename)

    # All checks passed; return True for convenience
    return True

def files_list(path):
    """Return the files in ``path``."""
    import os
    from pathlib import Path
    p = Path(path)
    if not p.exists():
        raise FileNotFoundError(f"Path does not exist: {path}")
    try:
        if p.is_file():
            return [str(p.resolve())]
        if p.is_dir():
            return [str(f.resolve()) for f in p.iterdir() if f.is_file()]
        # For other types (symlinks, etc.) treat as file if it refers to a file
        if p.is_symlink() and Path(os.readlink(p)).exists():
            target = Path(os.readlink(p))
            if target.is_file():
                return [str(target.resolve())]
            if target.is_dir():
                return [str(f.resolve()) for f in target.iterdir() if f.is_file()]
    except OSError as exc:
        raise RuntimeError(f"Error accessing path '{path}': {exc}") from exc
    return []

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Directory or base path to join with filenames if they are relative.
    xmls : list of str
        List of XML file paths (full or relative).
    files : list of str
        List of files in the folder or zipfile (full or relative).

    Returns
    -------
    dict
        key: name of the XML file (basename without extension)
        value: list of file paths that belong to that XML file
    """
    import os

    # Validate input types
    if not isinstance(source, str):
        raise TypeError("source must be a string")
    if not hasattr(xmls, "__iter__") or isinstance(xmls, (str, bytes)):
        raise TypeError("xmls must be a list or iterable of strings")
    if not hasattr(files, "__iter__") or isinstance(files, (str, bytes)):
        raise TypeError("files must be a list or iterable of strings")

    # Normalize source path
    source = os.path.abspath(source) if source else ""

    # Build a mapping from XML base name to list of files
    result = {}

    # Preprocess xmls: compute base names and ensure uniqueness
    xml_bases = {}
    for xml_path in xmls:
        try:
            xml_base = os.path.splitext(os.path.basename(xml_path))[0]
        except Exception:
            continue
        if xml_base in xml_bases:
            raise ValueError(f"Duplicate XML base name detected: {xml_base}")
        xml_bases[xml_base] = xml_path
        result[xml_base] = []

    # Helper to normalize file path
    def normalize_path(p):
        if source and not os.path.isabs(p):
            return os.path.normpath(os.path.join(source, p))
        return os.path.normpath(p)

    # Iterate over all files and associate them with their XML base
    for file_path in files:
        try:
            file_base = os.path.splitext(os.path.basename(file_path))[0]
        except Exception:
            continue
        if file_base in result:
            full_path = normalize_path(file_path)
            result[file_base].append(full_path)

    return result

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Basic sanity checks
    if node is None:
        return None
    if not isinstance(pubdate_xpaths, (list, tuple)):
        return None
    for xpath_expr in pubdate_xpaths:
        try:
            result = node.xpath(xpath_expr)
        except Exception:
            # If the XPath is invalid or evaluation fails, skip to next
            continue
        if result:
            # Return the first matched element or value
            return result[0]
    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = '  ' * indent

    def _convert(obj, lvl):
        # Recursively convert objects to string
        if hasattr(obj, 'pretty') and callable(getattr(obj, 'pretty')):
            return obj.pretty(lvl, debug=debug)
        if isinstance(obj, dict):
            return '{' + ', '.join(f'{k}: {_convert(v, lvl)}' for k, v in obj.items()) + '}'
        if isinstance(obj, (list, tuple, set)):
            return '[' + ', '.join(_convert(item, lvl) for item in obj) + ']'
        return repr(obj)

    parts = []
    for key, value in self.__dict__.items():
        parts.append(f'{key}={_convert(value, indent + 1)}')
    return f'{indent_str}{self.__class__.__name__}({", ".join(parts)})'

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    try:
        unicode_type = unicode  # type in Python 2
    except NameError:
        unicode_type = type("").__class__  # in Python 3, str is unicode

    def _wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        # In Python 2, keep bytestrings; if a unicode string is returned, encode
        if sys.version_info[0] == 2 and isinstance(result, unicode_type):
            try:
                return result.encode("utf-8")
            except Exception:
                # Fall back to unicode's default encoding if utf-8 fails
                return result.encode("utf-8", "ignore")
        return result

    return _wrapper

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate input
    if pieces is None:
        raise TypeError("pieces must not be None")
    if isinstance(pieces, str):
        # Treat a single string as a single piece
        pieces = [pieces]
    try:
        it = iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of items (e.g., list, tuple, or str)")
    if not isinstance(style, str):
        raise TypeError("style must be a string")

    # Simple escape function for HTML
    def _escape_html(text):
        return (text.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace('"', "&quot;")
                    .replace("'", "&#039;"))

    # Prepare string representations of the pieces
    rendered_pieces = []
    for i, piece in enumerate(it, start=1):
        try:
            piece_text = str(piece)
        except Exception as exc:
            raise ValueError(f"Unable to convert piece #{i} to string: {exc}") from exc
        rendered_pieces.append(piece_text)

    # Render according to style
    if style.lower() == "plain":
        result = " ".join(rendered_pieces)
    elif style.lower() == "html":
        escaped = [_escape_html(p) for p in rendered_pieces]
        result = "".join(f"<span>{e}</span>" for e in escaped)
    elif style.lower() == "markdown":
        # For Markdown we keep the plaintext but could add simple formatting.
        result = " ".join(rendered_pieces)
    else:
        raise ValueError(f"Unsupported style '{style}'. Supported styles: plain, html, markdown")

    return result

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        if '+' in pieces:
            return '.'
    except TypeError:
        # pieces is not iterable (e.g. None); treat as no '+'
        pass
    return '+'

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS.

    Parameters
    ----------
    vcs : str
        Name or identifier of the version control system.
    method : callable, optional
        If provided, the handler function to register.
        If omitted, `register_vcs_handler` returns a decorator.
    """
    if method is None:
        def decorator(func):
            return _register_vcs_handler(vcs, func)
        return decorator
    return _register_vcs_handler(vcs, method)

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    stack = [self]
    while stack:
        obj = stack.pop()
        num_objects += 1

        ok = True

        # Validate object if requested
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    # Assume validate raises if object is invalid
                    obj.validate()
                elif getattr(obj, 'isValid', None) is not None:
                    ok = bool(obj.isValid())
            except Exception as e:
                ok = False
                if show_warnings:
                    msg = f"Warning: Validation failed for {type(obj).__name__}"
                    if getattr(obj, 'id', None):
                        msg += f" (id={obj.id})"
                    msg += f": {e}"
                    print(msg)

        # Check digest if requested
        if check_digests:
            try:
                digest_ok = True
                if hasattr(obj, 'check_digest'):
                    digest_ok = obj.check_digest()
                elif hasattr(obj, 'digest') and hasattr(obj, 'content'):
                    import hashlib
                    h = hashlib.sha256()
                    # assume content is string; otherwise encode appropriately
                    content = obj.content
                    if isinstance(content, str):
                        content = content.encode('utf-8')
                    h.update(content)
                    digest_ok = (h.hexdigest() == obj.digest)
                if not digest_ok:
                    ok = False
                    if show_warnings:
                        msg = f"Warning: Digest mismatch for {type(obj).__name__}"
                        if getattr(obj, 'id', None):
                            msg += f" (id={obj.id})"
                        print(msg)
            except Exception as e:
                ok = False
                if show_warnings:
                    msg = f"Warning: Digest check failed for {type(obj).__name__}"
                    if getattr(obj, 'id', None):
                        msg += f" (id={obj.id})"
                    msg += f": {e}"
                    print(msg)

        if ok:
            good_objects += 1

        # Gather children
        children = []
        try:
            children = list(obj)
        except Exception:
            if hasattr(obj, 'children'):
                try:
                    children = list(obj.children)
                except Exception:
                    pass
            elif hasattr(obj, 'elements'):
                try:
                    children = list(obj.elements)
                except Exception:
                    pass
        stack.extend(children)

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    from pathlib import Path

    # --- Validate configuration ------------------------------------
    root_attr = getattr(self, "root", None)
    if root_attr is None:
        raise AttributeError("Instance has no 'root' attribute to designate the OCFL storage root")

    root_path = Path(root_attr).expanduser().resolve()
    if not root_path:
        raise ValueError(f"Invalid root path: {root_attr}")

    # --- Create root directory ------------------------------------
    try:
        root_path.mkdir(parents=True, exist_ok=False)
    except FileExistsError:
        raise FileExistsError(f"OCFL storage root already exists at {root_path}") from None
    except OSError as exc:
        raise OSError(f"Could not create root directory '{root_path}': {exc}") from exc

    # --- Create mandatory subdirectories --------------------------
    try:
        (root_path / "objects").mkdir(exist_ok=False)
        (root_path / "objects" / "shipments").mkdir(exist_ok=False)
    except OSError as exc:
        raise OSError(f"Failed to create required OCFL directories under '{root_path}': {exc}") from exc

    # --- Create placeholder metadata files -----------------------
    try:
        (root_path / "manifest.json").write_text("{}\n", encoding="utf-8")
        (root_path / "objects" / "catalog.json").write_text("{}\n", encoding="utf-8")
    except OSError as exc:
        raise OSError(f"Failed to create metadata files under '{root_path}': {exc}") from exc

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        raise ValueError("version must be a non-empty string")

    # Find the first digit to separate any leading non-numeric prefix (e.g., 'v')
    first_digit = None
    for i, ch in enumerate(version):
        if ch.isdigit():
            first_digit = i
            break
    if first_digit is None:
        raise ValueError("version string must contain at least one digit")

    prefix = version[:first_digit]
    numeric_part = version[first_digit:]

    parts = numeric_part.split('.')
    # Validate numeric parts
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"Invalid numeric component '{p}' in version '{version}'")

    last_part = parts[-1]
    width = len(last_part)
    new_last = str(int(last_part) + 1)
    # Preserve zero padding if possible
    if len(new_last) < width:
        new_last = new_last.zfill(width)
    parts[-1] = new_last

    return prefix + '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os

    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return

    # Helper to read an inventory file into a dict: {file: digest}
    def _read_inventory(inv_path):
        digests = {}
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file not found: {inv_path}")
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue  # malformed line, skip
                    path, digest = parts
                    digests[path] = digest
        except Exception as exc:
            raise IOError(f"Failed to read inventory '{inv_path}': {exc}") from exc
        return digests

    # Determine root path for inventories (assumed to be the object's base dir)
    # Use an attribute that should exist on the instance; fall back to os.getcwd()
    base_dir = getattr(self, "docroot", os.getcwd())

    root_inventory_path = os.path.join(base_dir, "inventory.xml")
    try:
        root_digests = _read_inventory(root_inventory_path)
    except Exception:
        # If root inventory is missing or unreadable, treat as empty
        root_digests = {}

    # Store differences between each version inventory and the root
    inventory_differences = {}

    for v_dir in version_dirs:
        # Construct path to the inventory in this version directory
        inv_path = os.path.join(base_dir, v_dir, "inventory.xml")
        try:
            v_digests = _read_inventory(inv_path)
        except FileNotFoundError as nf:
            # If a version is missing its inventory, we treat it as an error
            raise ValueError(f"Version directory '{v_dir}' lacks a required inventory file.") from nf
        except Exception as exc:
            # Any other IO errors are propagated as runtime errors
            raise RuntimeError(f"Error reading inventory for version '{v_dir}': {exc}") from exc

        # Compare digests against the root inventory
        differing_files = []
        for key, digest in v_digests.items():
            root_digest = root_digests.get(key)
            if root_digest is None or root_digest != digest:
                differing_files.append(key)

        if differing_files:
            inventory_differences[v_dir] = differing_files

    # Store the differences so other methods can access them
    # Use a predictable attribute name
    setattr(self, "_inventory_differences", inventory_differences)

    # Method returns the diffs dictionary for convenience
    return inventory_differences

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=* Namaste files to determine the directory type.
    """
    import os, fnmatch

    # Resolve to absolute path
    path = os.path.abspath(path)

    # Path does not exist
    if not os.path.exists(path):
        return f"not found: {path}"

    # File path
    if os.path.isfile(path):
        return 'file'

    # Directory path
    if os.path.isdir(path):
        # Directory could be a root if it contains subfolder 'objects'
        has_objects = os.path.isdir(os.path.join(path, 'objects'))

        # Look for any Namaste file "0=*"
        def has_namaste(p):
            try:
                for entry in os.listdir(p):
                    if fnmatch.fnmatch(entry, '0=*') and os.path.isfile(os.path.join(p, entry)):
                        return True
            except Exception:
                pass
            return False

        if has_objects:
            # probable root; confirm Namaste file in the root
            if has_namaste(path):
                return 'root'
            else:
                return f"root? missing Namaste file in {path}"
        else:
            # probable object; confirm Namaste file
            if has_namaste(path):
                return 'object'
            else:
                return f"object? missing Namaste file in {path}"

    # If we get here, something unexpected
    return f"unknown type for {path}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    # Validate inputs
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    if not isinstance(bug_ids, (list, tuple)):
        raise TypeError("bug_ids must be a list or tuple of bug identifiers")

    # Extract existing ids from params if any
    existing_ids = set()
    if 'ids' in params:
        ids_val = params['ids']
        if isinstance(ids_val, str):
            if ids_val:
                try:
                    existing_ids.update(int(i.strip()) for i in ids_val.split(',') if i.strip())
                except ValueError:
                    raise ValueError("Existing 'ids' value must be a comma-separated list of integers")
        else:
            try:
                existing_ids.update(int(i) for i in ids_val)
            except Exception:
                raise ValueError("Existing 'ids' value must be iterable of integers")

    # Add new bug ids, ensuring they are integers
    for bid in bug_ids:
        try:
            bid_int = int(bid)
        except Exception:
            raise ValueError(f"bug_ids must be integers or convertible to integers, got {bid!r}")
        existing_ids.add(bid_int)

    # Update the params dict with the combined, sorted list of ids
    if existing_ids:
        params['ids'] = ','.join(str(i) for i in sorted(existing_ids))
    else:
        # If no ids result, ensure the key is absent
        params.pop('ids', None)

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping(node):
        try:
            return isinstance(node, MappingNode)
        except NameError:
            return False

    # Recursive merge of two MappingNodes
    def merge_mapping_nodes(n1, n2):
        # Build a lookup for n1's pairs by key string
        existing_pairs = n1.value  # list of (key_node, val_node)
        new_pairs = n2.value
        key_to_index = {k.value: (i, p) for i, (k, p) in enumerate(existing_pairs)}
        # Start with a shallow copy of existing pairs
        merged_pairs = existing_pairs[:]
        for k_node, v_node in new_pairs:
            k = k_node.value
            if k in key_to_index:
                idx, (_, existing_val) = key_to_index[k]
                if is_mapping(existing_val) and is_mapping(v_node):
                    merged_val = merge_mapping_nodes(existing_val, v_node)
                else:
                    merged_val = v_node
                merged_pairs[idx] = (k_node, merged_val)
            else:
                merged_pairs.append((k_node, v_node))
                key_to_index[k] = (len(merged_pairs) - 1, (k_node, v_node))
        # Return a new MappingNode with same tag and merged pairs
        return type(n1)(tag=n1.tag, value=merged_pairs)

    # Main merging logic
    merged = {}
    key_to_keynode = {}
    key_order = []

    for key_node, value_node in nodes:
        # Defensive: ensure key_node is scalar
        try:
            key_val = key_node.value
        except AttributeError:
            # If key_node doesn't have value, use default string representation
            key_val = str(key_node)

        if key_val not in merged:
            merged[key_val] = value_node
            key_to_keynode[key_val] = key_node
            key_order.append(key_val)
        else:
            existing = merged[key_val]
            if is_mapping(existing) and is_mapping(value_node):
                merged[key_val] = merge_mapping_nodes(existing, value_node)
            else:
                merged[key_val] = value_node

    # Construct result in original key order, using the first key_node seen
    result = []
    for key_val in key_order:
        key_node = key_to_keynode[key_val]
        result.append((key_node, merged[key_val]))

    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError('Expected an argparse.ArgumentParser instance')
    flags = []
    for action in actions:
        # Each action may have multiple option strings (e.g., ['-a', '--alpha'])
        # Extend the list with all of them.
        flags.extend(action.option_strings)
    return ' '.join(flags)

def deep_merge_nodes(nodes):
    """
    Merge a list of YAML mapping nodes that may contain duplicate keys.
    The last value wins in case of non-mapping conflicts.
    """
    def is_mapping(node):
        return hasattr(node, "value") and isinstance(node.value, list)

    def merge_nodes(a, b):
        """
        Merge two nodes recursively.
        If both are mappings, deep-merge their contents.
        Otherwise, the second node wins.
        """
        if is_mapping(a) and is_mapping(b):
            # Build dictionaries of existing key -> (key_node, value_node)
            dict_a = {k.value: (k, v) for k, v in a.value}
            for k_node, val in b.value:
                key = k_node.value
                if key in dict_a:
                    merged_val = merge_nodes(dict_a[key][1], val)
                    dict_a[key] = (k_node, merged_val)
                else:
                    dict_a[key] = (k_node, val)
            # Preserve original order from a, then new keys
            new_pairs = list(dict_a.values())
            return type(a)(tag=a.tag, value=new_pairs)
        else:
            # Not both mappings: the later value wins
            return b

    # Maintain order of first occurrences of keys
    merged = {}
    key_order = []

    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged:
            merged[key] = merge_nodes(merged[key], val_node)
        else:
            merged[key] = val_node
            key_order.append(key)

    # Build the final merged list preserving first-key order
    result = [(next(k for k in nodes if k[0].value == key)[0], merged[key]) for key in key_order]
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space‑separated string.
    """
    import argparse
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    try:
        # Collect the option strings from each action in the order they were added.
        flags = [opt for action in parser._actions for opt in action.option_strings]
        return ' '.join(flags)
    except Exception:
        # In case of any unexpected error, return an empty string rather than
        # propagating the exception to callers that may not handle it.
        return ""

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    def _generator():
        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]

    return _generator()

def _dictsum(dicts):
    """Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise ValueError("Input iterable is None")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args."""
    if not isinstance(url, str):
        raise TypeError(f"url must be a string, got {type(url).__name__}")
    if url_args is None:
        return url

    # Support both mapping (named placeholders) and sequence (positional placeholders)
    if isinstance(url_args, (list, tuple)):
        try:
            return url.format(*url_args)
        except IndexError as exc:
            raise IndexError(f"Not enough values to replace placeholders in URL: {exc}") from None

    if not isinstance(url_args, dict):
        raise TypeError(f"url_args must be a dict or sequence, got {type(url_args).__name__}")

    try:
        return url.format(**url_args)
    except KeyError as exc:
        # Provide clearer error for missing placeholder
        missing = exc.args[0]
        raise KeyError(f"Missing value for URL placeholder {{'{missing}'}}") from None

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None objects are obviously None
    if val is None:
        return True
    # Accept common textual representations of None/XML blank etc.
    if isinstance(val, str):
        cleaned = val.strip().lower()
        # Empty string or common markers are treated as None
        return cleaned in {"", "none", "null", "na", "n/a", "undefined"}
    # Non-string types are considered not representing None
    return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, (list, tuple)) or not alphabet:
        raise ValueError("alphabet must be a non-empty list or tuple of characters")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two symbols to represent numbers")
    if number < 0:
        raise ValueError("negative numbers are not supported")
    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
    digits_reverse = digits[::-1]  # most significant digit first
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
        pad_char = alphabet[0]
        if len(digits_reverse) < padding:
            digits_reverse = [pad_char] * (padding - len(digits_reverse)) + digits_reverse
    return "".join(digits_reverse)

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Basic type checks
    if not isinstance(flow_params, (dict, list)):
        raise TypeError("flow_params must be a dict or list")
    try:
        register_number = int(register_number)
    except Exception as exc:
        raise TypeError("register_number must be an integer or convertible to int") from exc

    def _replace(obj):
        if isinstance(obj, dict):
            for k, v in list(obj.items()):
                if v == register_value:
                    obj[k] = register_number
                else:
                    _replace(v)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                if item == register_value:
                    obj[i] = register_number
                else:
                    _replace(item)

    _replace(flow_params)  # modify in place, return None as per original contract.

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError('Expected a class type, got %r' % type(cls))

    def _rec(c):
        subs = set()
        try:
            sub_list = c.__subclasses__()
        except AttributeError:
            # not a class or doesn't support subclasses
            return subs
        for sub in sub_list:
            subs.add(sub)
            subs.update(_rec(sub))
        return subs

    return list(_rec(cls))

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet cannot be empty.")
    # Create a mapping from character to its numeric value
    mapping = {char: idx for idx, char in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"Character {ch!r} not found in alphabet.")
        result = result * base + mapping[ch]
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    if len(name) >= 2 and ((name[0] == name[-1]) and name[0] in ('"', "'")):
        return name[1:-1]
    # If only leading or trailing quote, strip them as well
    # But preserve if mismatched
    if name and name[0] in ('"', "'"):
        name = name[1:]
    if name and name[-1] in ('"', "'"):
        name = name[:-1]
    return name

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ["git", "ls-files", "--others", "--ignored", "--exclude-standard"],
            universal_newlines=True,
            stderr=subprocess.DEVNULL,
        )
    except (subprocess.CalledProcessError, FileNotFoundError):
        # If git isn't available or the command fails, return an empty string
        return ""
    except Exception as e:
        # Catch any other unexpected exception and return empty string
        return ""

    # Convert output string to a non-empty list of files
    files = [line.strip() for line in output.splitlines() if line.strip()]
    # If a pattern was provided, filter the list
    if ignored:
        try:
            import fnmatch
            files = [f for f in files if fnmatch.fnmatch(f, ignored)]
        except Exception:
            # If pattern filtering fails, ignore the error and keep all files
            pass

    # Sort the final list
    files.sort()
    # Join with commas
    return ",".join(files)

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    # Input validation
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Ensure config_filename is not empty and not a directory path
    if not config_filename:
        raise ValueError("config_filename must not be empty")
    if os.path.isdir(config_filename):
        raise ValueError(f"config_filename '{config_filename}' refers to a directory")

    # Create any necessary directories
    dirname = os.path.dirname(config_filename)
    if dirname:
        try:
            os.makedirs(dirname, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(f"Unable to create directories for {config_filename}: {exc}") from exc

    # Check for existing file
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"Configuration file '{config_filename}' already exists and overwrite is False")

    # Write the rendered configuration to the file
    try:
        with open(config_filename, "w", encoding="utf-8") as f:
            f.write(rendered_config)
    except OSError as exc:
        raise RuntimeError(f"Failed to write configuration file '{config_filename}': {exc}") from exc

    # Set the file permissions
    try:
        os.chmod(config_filename, mode)
    except OSError as exc:
        raise RuntimeError(f"Failed to set permissions for '{config_filename}': {exc}") from exc

    return None

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern

    Arguments:
        pattern (str): The string to be compiled as a regex pattern.
        strip (bool): Whether to strip surrounding whitespace from the pattern. Defaults to True.

    Returns:
        re.Pattern: The compiled regular expression object.

    Raises:
        TypeError: If ``pattern`` is not a string.
        ValueError: If the pattern cannot be compiled into a valid regular expression.
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")

    if strip:
        pattern = pattern.strip()

    try:
        return re.compile(pattern)
    except re.error as exc:
        raise ValueError(f"Invalid regex pattern: {exc}") from exc

def run_command(commands, args=None, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalise parameters
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a sequence of strings")
    if args is None:
        args = []
    if isinstance(args, str):
        args = [args]
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a string, list or tuple of strings")
    # Build full command list
    full_cmd = list(commands) + list(args)
    if not full_cmd:
        raise ValueError("No command specified")
    # Verbose output
    if verbose:
        print(f"Executing command: {' '.join(full_cmd)}")
    try:
        # When hide_stderr is True we discard any stderr output by piping it to DEVNULL
        stderr_pipe = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_pipe,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as exc:
        # Optionally report stderr on failure
        if verbose and not hide_stderr:
            print(f"Error output:\n{exc.stderr}")
        raise RuntimeError(
            f"Command '{' '.join(full_cmd)}' failed with exit code {exc.returncode}"
        ) from exc
    # Show output if verbose
    if verbose and not hide_stderr:
        if result.stdout:
            print("Command output:")
            print(result.stdout)
        if result.stderr:
            print("Command error output:")
            print(result.stderr)
    return result

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        if isinstance(target, ipaddress.IPv4Address):
            return True
        if isinstance(target, ipaddress.IPv6Address):
            return False
        return isinstance(ipaddress.ip_address(target), ipaddress.IPv4Address)
    except (TypeError, ValueError):
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    yaml_kwargs = {"default_flow_style": False, "allow_unicode": True}
    if dumper is None:
        try:
            # Try to use safe_dump first (PyYAML >= 5)
            return yaml.safe_dump(obj, **yaml_kwargs)
        except AttributeError:
            # Fallback for older PyYAML versions or custom usage
            return yaml.dump(obj, **yaml_kwargs)
    else:
        # The caller supplied a custom dumper; use it explicitly
        return yaml.dump(obj, Dumper=dumper, **yaml_kwargs)

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and normalize shape
    if shape is None:
        raise ValueError("shape must not be None")
    if isinstance(shape, int):
        shape = (shape,)
    elif isinstance(shape, (list, tuple)):
        shape = tuple(shape)
    else:
        raise TypeError(f"shape must be an int, tuple, or list, got {type(shape).__name__}")
    if not shape:
        raise ValueError("shape cannot be empty")
    # Ensure dtype is a numpy.dtype instance
    if dtype is None:
        dtype = np.dtype("float32")
    elif isinstance(dtype, str):
        dtype = np.dtype(dtype)
    elif not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception as e:
            raise TypeError(f"Invalid dtype: {dtype}") from e
    # Create and return the array
    return np.zeros(shape, dtype=dtype)

def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    mean = 0.2
    sigma = 0.1
    return np.exp(-((x - mean) ** 2) / (2 * sigma ** 2)) / (sigma * np.sqrt(2 * np.pi))

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        instance = cls()
        if values is None:
            return instance
        # Accept a single string as a one‑item sequence
        try:
            iter(values)
        except TypeError:
            values = [values]
        for raw in values:
            if raw is None:
                continue
            raw = str(raw).strip()
            if not raw:
                continue
            try:
                # Try to create a bookmark object from the raw string if such a
                # factory method exists.  If it does not exist or fails, we fall
                # back to storing the raw string directly.
                bookmark = getattr(cls, "Bookmark", None)
                if bookmark and hasattr(bookmark, "from_raw_value"):
                    bookmark_obj = bookmark.from_raw_value(raw)
                else:
                    bookmark_obj = raw
            except Exception:
                # In case something unexpected happened, use the raw value
                bookmark_obj = raw
            instance.append(bookmark_obj)
        return instance

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Name of the function implies we want to return a tuple
    # (sequence object, originating type). If *seq* is already a
    # list or tuple we return it unchanged.  For other iterables
    # we materialise them into a list.  If *seq* is None we return an
    # empty list and the type ``NoneType``.
    #
    # Parameters:
    #   seq      : an arbitrary object or iterable
    #   bufsize  : optional buffer size hint (currently unused)
    #
    # Returns:
    #   tuple (sequence, type)

    # Handle None explicitly
    if seq is None:
        return [], type(seq)

    # If it is already a list or tuple, return it unchanged
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    # Try to materialise into a list
    try:
        seq_list = list(seq)
        return seq_list, type(seq)
    except Exception:
        # Not iterable, wrap it
        return [seq], type(seq)

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Attempt to import the specific exception if available
    try:
        from . import LenaValueError
    except Exception:
        class LenaValueError(ValueError):
            """Fallback exception for missing module."""
            pass

    # Helper to multiply values generically
    def _mult(value, factor):
        try:
            # NumPy array or similar supports element‑wise multiplication
            return value * factor
        except Exception:
            # Fall back to Python list/tuple handling
            if isinstance(value, (list, tuple)):
                return type(value)(_mult(v, factor) for v in value)
            # Scalar numeric
            return value * factor

    # Determine current scale attribute
    if hasattr(self, "scale"):
        current_scale = self.scale
    elif hasattr(self, "_scale"):
        current_scale = self._scale
    else:
        raise ValueError("Graph object has no scale attribute")

    if other is None:  # Getter
        return current_scale

    # Setter: other must be numeric
    if not isinstance(other, (int, float)):
        raise TypeError(f"Expected numeric `other`, got {type(other).__name__}")

    # Check for unknown or zero scale
    if current_scale is None or float(current_scale) == 0.0:
        raise LenaValueError("Cannot rescale graph with undefined or zero scale")

    factor = float(other) / float(current_scale)

    # Find all coordinate attributes (x, y, z or any other numeric attributes)
    coords = []
    for name in ("x", "y", "z"):
        if hasattr(self, name):
            coords.append(name)
    # If no standard coords, inspect all attributes for numeric types
    if not coords:
        for attr_name, attr_val in vars(self).items():
            if isinstance(attr_val, (int, float)):
                coords.append(attr_name)
    if not coords:
        raise ValueError("Could not identify any coordinate attributes to rescale")

    last_coord = coords[-1]
    # Rescale the coordinate
    try:
        current_val = getattr(self, last_coord)
        setattr(self, last_coord, _mult(current_val, factor))
    except Exception as exc:
        raise LenaValueError(f"Error rescaling coordinate '{last_coord}': {exc}") from exc

    # Rescale corresponding error attribute if present
    err_name = f"{last_coord}err"
    if hasattr(self, err_name):
        try:
            current_err = getattr(self, err_name)
            setattr(self, err_name, _mult(current_err, factor))
        except Exception as exc:
            raise LenaValueError(f"Error rescaling error '{err_name}': {exc}") from exc

    # Update the stored scale if it exists
    if hasattr(self, "scale"):
        self.scale = other
    elif hasattr(self, "_scale"):
        self._scale = other

    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate argument
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError(
            f"get_coordinate must be 'left', 'right' or 'middle', got '{get_coordinate}'"
        )

    # Retrieve histogram edges and bin contents
    try:
        edges = hist.edges
    except AttributeError:
        try:
            edges = hist.bin_edges
        except AttributeError:
            raise AttributeError(
                "Histogram object must have an 'edges' or 'bin_edges' attribute"
            )

    try:
        bin_values = hist.bins
    except AttributeError:
        try:
            bin_values = hist.bin_contents
        except AttributeError:
            raise AttributeError(
                "Histogram object must have a 'bins' or 'bin_contents' attribute"
            )

    n_bins = len(bin_values)
    if len(edges) != n_bins + 1:
        raise ValueError(
            f"Expected {n_bins+1} edges for {n_bins} bins, got {len(edges)}"
        )

    # Prepare output points
    points = []
    for i in range(n_bins):
        left_edge = edges[i]
        right_edge = edges[i + 1]
        if get_coordinate == "left":
            coord = left_edge
        elif get_coordinate == "right":
            coord = right_edge
        else:  # middle
            coord = (left_edge + right_edge) / 2.0

        # Extract bin value, possibly using make_value
        content = bin_values[i]
        if make_value is not None:
            try:
                processed = make_value(content)
            except Exception as exc:
                raise ValueError(
                    f"make_value function raised an exception for bin {i}: {exc}"
                ) from exc
        else:
            processed = content

        # Build point tuple
        if isinstance(processed, (tuple, list)):
            point = (coord,) + tuple(processed)
        else:
            point = (coord, processed)

        points.append(point)

    # Determine graph scale
    graph_scale = None
    if scale is True:
        graph_scale = getattr(hist, "scale", None)
    elif scale is not None:
        graph_scale = scale

    # Create the graph object.  We assume a Graph class is available
    # in the current namespace with a suitable initializer.
    try:
        graph = Graph(points=points, field_names=field_names, scale=graph_scale)
    except Exception as exc:
        # Fallback: return a simple dict if Graph is not available
        graph = {
            "points": points,
            "field_names": field_names,
            "scale": graph_scale,
        }
    return graph

def verifyObject(iface, candidate, tentative=False):
        """
        Verify that *candidate* might correctly provide *iface*.

        This involves:

        - Making sure the candidate claims that it provides the
          interface using ``iface.providedBy`` (unless *tentative* is `True`,
          in which case this step is skipped). This means that the candidate's class
          declares that it `implements <zope.interface.implementer>` the interface,
          or the candidate itself declares that it `provides <zope.interface.provider>`
          the interface

        - Making sure the candidate defines all the necessary methods

        - Making sure the methods have the correct signature (to the
          extent possible)

        - Making sure the candidate defines all the necessary attributes

        :return bool: Returns a true value if everything that could be
        checked passed.
        :raises zope.interface.Invalid: If any of the previous
        conditions does not hold.

        .. versionchanged:: 5.0
            If multiple methods or attributes are invalid, all such errors
            are collected and reported. Previously, only the first error was reported.
            As a special case, if only one such error is present, it is raised
            alone, like before.
        """
        import inspect
        from zope.interface import Invalid

        errors = []

        # 1. Check the interface declaration
        if not tentative:
            try:
                if not iface.providedBy(candidate):
                    errors.append("Candidate does not declare that it provides interface %s." % iface.__name__)
            except Exception as exc:
                errors.append("Error checking provides: %s" % exc)

        # Helper to compare signatures roughly
        def signatures_match(iface_sig, candidate_sig):
            # Convert both to list of positional params (excluding * and **)
            iface_params = [p for p in iface_sig.parameters.values()
                            if p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD,
                                      inspect.Parameter.POSITIONAL_ONLY,
                                      inspect.Parameter.ARGS)]
            cand_params = [p for p in candidate_sig.parameters.values()
                            if p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD,
                                      inspect.Parameter.POSITIONAL_ONLY,
                                      inspect.Parameter.ARGS)]

            # Interface methods include 'self' as first param; candidate bound methods omit it
            # Treat mismatch by checking lengths after dropping the first param of iface
            if iface_params and iface_params[0].name == 'self':
                iface_params = iface_params[1:]

            return len(iface_params) == len(cand_params)

        # 2. Check methods
        try:
            iface_methods = getattr(iface, 'methods', lambda: [])()
        except Exception:
            iface_methods = []

        for m in iface_methods:
            name = m.__name__
            if not hasattr(candidate, name):
                errors.append("Missing method '%s' required by interface %s." % (name, iface.__name__))
                continue
            cand_attr = getattr(candidate, name)
            if not callable(cand_attr):
                errors.append("Attribute '%s' exists but is not callable as required by interface %s." % (name, iface.__name__))
                continue
            try:
                iface_sig = inspect.signature(m)
            except Exception:
                iface_sig = None
            try:
                cand_sig = inspect.signature(cand_attr)
            except Exception:
                cand_sig = None
            if iface_sig and cand_sig:
                if not signatures_match(iface_sig, cand_sig):
                    errors.append("Signature of method '%s' does not match interface %s." % (name, iface.__name__))

        # 3. Check attributes
        try:
            iface_attrs = getattr(iface, 'attributes', lambda: [])()
        except Exception:
            iface_attrs = []

        for a in iface_attrs:
            name = a.__name__
            if not hasattr(candidate, name):
                errors.append("Missing attribute '%s' required by interface %s." % (name, iface.__name__))

        # Raise collected errors or return True
        if errors:
            if len(errors) == 1:
                raise Invalid(errors[0])
            else:
                raise Invalid("Multiple interface errors: " + "; ".join(errors))
        return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate input
    if not isinstance(bases, (list, tuple)):
        raise TypeError("bases must be a list or tuple of base classes")
    for b in bases:
        if not isinstance(b, type):
            raise TypeError("base %r is not a class" % b)

    # Collect all metaclasses from bases
    metaclasses = set(type(b) for b in bases)

    # Include explicit metaclass if provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass %r is not a class" % explicit_mc)
        metaclasses.add(explicit_mc)

    # If no metaclasses found, default to the built‑in metaclass 'type'
    if not metaclasses:
        return type

    # Find the most derived metaclass that is a subclass of all others
    candidate = None
    for m in metaclasses:
        if all(issubclass(m, other) for other in metaclasses):
            if candidate is None:
                candidate = m
            else:
                # More than one candidate, ambiguous
                raise TypeError("Metaclass conflict: multiple candidates %r and %r" % (candidate, m))

    if candidate is None:
        raise TypeError("Metaclass conflict: no common metaclass for %r" % (metaclasses,))

    return candidate

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    else:
        if default is not __marker:
            return default
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the mapping is not empty
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    # Attempt to locate the usage counter dictionary
    freq_dict = None
    if hasattr(self, '_freq'):
        freq_dict = getattr(self, '_freq')
    else:
        # If the values expose a `freq` (usage) attribute, construct a dict
        try:
            freq_dict = {k: getattr(v, 'freq', 0) for k, v in self.items()}
        except Exception:
            raise NotImplementedError(
                "Cannot determine usage counts; "
                "the object does not provide a `_freq` attribute or "
                "`freq` attributes on its values."
            )
    # Identify the key with the least usage count
    try:
        min_key = min(freq_dict, key=lambda k: freq_dict[k])
    except Exception as exc:
        raise RuntimeError("Failed to determine least frequently used key") from exc
    # Retrieve and remove the value
    value = self.pop(min_key)
    # Clean up the usage counter if it belongs to the object
    if hasattr(self, '_freq') and min_key in getattr(self, '_freq'):
        del getattr(self, '_freq')[min_key]
    return min_key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Prefer a dedicated storage if the class uses an internal OrderedDict.
    # Most LRU caches keep the mapping in `self._store`.
    if hasattr(self, "_store") and hasattr(self._store, "popitem"):
        try:
            return self._store.popitem(last=False)
        except KeyError:
            raise KeyError("popitem(): dictionary is empty")
    # Fallback: try the base class implementation.
    try:
        # Use `super()` in case the class inherits from a mapping type.
        return super().popitem()
    except AttributeError as exc:
        # If the object has no popitem method we signal an error.
        raise AttributeError(
            "The object does not have a popitem method or an internal store."
        ) from exc
    except KeyError:
        raise KeyError("popitem(): dictionary is empty") from None

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    try:
        # Prefer to use the most recent key if ordering is supported
        key = next(reversed(self))
    except Exception:
        # Fallback for non-reversible mappings: take an arbitrary item
        try:
            key, value = next(iter(self.items()))
            self.pop(key)
            return key, value
        except StopIteration:
            raise KeyError('popitem(): dictionary is empty')
    value = self.pop(key)
    return key, value

def isoparse(self, dt_str):
        """Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

        :param dt_str: A string or stream containing only an ISO-8601 datetime string
        :return: Returns a :class:`datetime.datetime` representing the string.
        """
        import datetime
        try:
            from dateutil.tz import tzoffset, tzutc
        except ImportError as exc:
            raise ImportError("dateutil.tz is required for parsing timezone information") from exc

        if hasattr(dt_str, 'read'):
            try:
                dt_str = dt_str.read().strip()
            except Exception as exc:
                raise ValueError("stream.read() failed") from exc
        dt_str = str(dt_str).strip()

        # Handle timezone suffix
        tzinfo = None
        tzmatch = None
        if dt_str.endswith('Z'):
            tzinfo = tzutc()
            dt_str = dt_str[:-1]
        else:
            # match trailing +HH:MM, +HHMM, +HH or -HH:MM, -HHMM, -HH
            tzmatch = datetime.datetime.strptime(dt_str[-6:], "%z") if re.search(r'([+-]\d{2}:?\d{2})$', dt_str) else None
            if tzmatch is None and re.search(r'([+-]\d{2}$|[+-]\d{2}\d{2}$|[+-]\d{2}:\d{2}$)', dt_str):
                # parse with regex
                tzsign = dt_str[-1]
                # We'll find last +/- occurrence
                pos = dt_str.rfind('+') if '+' in dt_str else dt_str.rfind('-')
                if pos != -1:
                    tz_part = dt_str[pos:]
                    dt_str = dt_str[:pos]
                    hour = int(tz_part.split(':')[0][1:3])
                    minute = 0
                    if ':' in tz_part:
                        minute = int(tz_part.split(':')[1])
                    elif len(tz_part) == 4 or len(tz_part) == 5:
                        minute = int(tz_part[3:5])
                    offset_sec = hour * 3600 + minute * 60
                    if tz_part.startswith('-'):
                        offset_sec = -offset_sec
                    tzinfo = tzoffset(None, offset_sec)

        # Split date and time parts
        if 'T' in dt_str:
            date_part, time_part = dt_str.split('T', 1)
        else:
            date_part = dt_str
            time_part = ''

        # Parse date portion
        year = month = day = None
        # YYYY-MM-DD or YYYYMMDD
        m = re.match(r'^(\d{4})-?(\d{2})-?(\d{2})$', date_part)
        if m:
            year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
        else:
            m = re.match(r'^(\d{4})-?(\d{2})$', date_part)
            if m:
                year, month = int(m.group(1)), int(m.group(2))
                day = 1
            else:
                m = re.match(r'^(\d{4})$', date_part)
                if m:
                    year = int(m.group(1))
                    month, day = 1, 1
                else:
                    # ISO week date YYYY-Www or YYYYWww
                    m = re.match(r'^(\d{4})-?W(\d{2})-?(\d?)$', date_part)
                    if m:
                        year = int(m.group(1))
                        week = int(m.group(2))
                        day_of_week = m.group(3)
                        day_of_week = int(day_of_week) if day_of_week else 1
                        try:
                            wd = datetime.date.fromisocalendar(year, week, day_of_week)
                            year, month, day = wd.year, wd.month, wd.day
                        except Exception as exc:
                            raise ValueError(f"Invalid ISO week date: {date_part}") from exc
                    else:
                        raise ValueError(f"Unrecognized date format: {date_part}")

        # Parse time portion
        hour = minute = second = microsecond = 0
        if time_part:
            # Replace comma decimal separator with dot
            time_part = time_part.replace(',', '.')
            # Split hour part with optional minute/second
            if ':' in time_part:
                parts = time_part.split(':')
                try:
                    hour = int(parts[0])
                    if len(parts) > 1:
                        minute = int(parts[1])
                    if len(parts) > 2:
                        sec_part = parts[2]
                        if '.' in sec_part:
                            sec, frac = sec_part.split('.', 1)
                            second = int(sec)
                            frac = (frac + '000000')[:6]
                            microsecond = int(frac)
                        else:
                            second = int(sec_part)
                except Exception as exc:
                    raise ValueError(f"Invalid time format: {time_part}") from exc
            else:
                # non‑colon forms: hh, hhmm, hhmmss
                try:
                    if len(time_part) == 6:  # hhmmss
                        hour = int(time_part[:2])
                        minute = int(time_part[2:4])
                        second = int(time_part[4:6])
                    elif len(time_part) == 4:  # hhmm
                        hour = int(time_part[:2])
                        minute = int(time_part[2:4])
                    elif 1 <= len(time_part) <= 2:  # hh
                        hour = int(time_part)
                    else:
                        raise ValueError
                except Exception as exc:
                    raise ValueError(f"Invalid time format: {time_part}") from exc

        # Handle midnight special case 24:00:00
        if hour == 24 and minute == 0 and second == 0 and microsecond == 0:
            try:
                d = datetime.date(year, month, day) + datetime.timedelta(days=1)
                year, month, day = d.year, d.month, d.day
                hour = 0
            except Exception:
                pass

        try:
            return datetime.datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo)
        except Exception as exc:
            raise ValueError(f"Error constructing datetime: {exc}") from exc

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # 1. Check the User-Agent header for a hint
    try:
        ua = request.headers.get('User-Agent', '')
        if ua.lower().startswith('diaspora'):
            return True
    except Exception:
        pass

    # 2. Try to read JSON body
    data = None
    try:
        # Some web frameworks expose a .json() method; others use .get_json()
        if hasattr(request, 'json'):
            json_attr = getattr(request, 'json')
            if callable(json_attr):
                data = json_attr()
            else:
                data = json_attr
        elif hasattr(request, 'get_json'):
            data = request.get_json()
    except Exception:
        pass

    if not isinstance(data, dict):
        return False

    # 3. Public message detection
    if 'public' in data or 'object' in data.get('public', {}):
        return True

    # 4. Private message detection
    if 'privatemessage' in data or 'message' in data:
        return True

    # 5. Legacy payload: older messages might just contain a 'data' key
    if 'data' in data:
        return True

    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    import datetime

    if dt is None:
        raise ValueError("dt must not be None")

    # If it's already a datetime or date instance, format directly
    if isinstance(dt, (datetime.datetime, datetime.date)):
        # Ensure we use date component only
        return dt.strftime("%Y-%m-%d")

    # If it's a string, try to interpret it as a date/time
    if isinstance(dt, str):
        # Try ISO format parsing first
        try:
            parsed = datetime.datetime.fromisoformat(dt)
        except ValueError:
            # Fall back to common format without time
            try:
                parsed = datetime.datetime.strptime(dt, "%Y-%m-%d")
            except Exception:
                raise ValueError(
                    f"Could not parse string '{dt}' as a date or datetime."
                ) from None
        return parsed.strftime("%Y-%m-%d")

    raise TypeError(
        f"Unsupported type for dt: {type(dt).__name__}. "
        "Expected datetime, date, or str."
    )

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError(f"text must be a str instance, got {type(text).__name__}")
    if not text:
        return text

    # Use the regex module via __import__ to avoid top-level imports
    try:
        re = __import__('re')
    except Exception as exc:
        raise RuntimeError("Failed to import the 're' module.") from exc

    # Patterns for markdown links [text](url) and plain URLs
    md_pattern = re.compile(r'\[([^\]]+)\]\((https?://[^\)]+)\)', flags=re.IGNORECASE)
    url_pattern = re.compile(r'(?i)\b((?:https?://|ftp://|www\.)[^\s<]+)', flags=re.IGNORECASE)

    def _make_link(match, href_attr=None, link_text=None):
        """Internal helper to construct an <a> tag with target and rel attributes."""
        href = href_attr if href_attr else match.group(0)
        if not href.startswith(('http://', 'https://', 'ftp://')):
            href = 'http://' + href
        display = link_text if link_text is not None else match.group(0)
        return f'<a href="{href}" target="_blank" rel="noopener">{display}</a>'

    # Replace markdown links first to avoid double replacement
    try:
        processed = md_pattern.sub(lambda m: _make_link(m, href_attr=m.group(2), link_text=m.group(1)), text)
    except re.error as e:
        raise ValueError(f"Markdown regex error: {e}") from e

    # Replace any remaining plain URLs
    try:
        processed = url_pattern.sub(lambda m: _make_link(m), processed)
    except re.error as e:
        raise ValueError(f"URL regex error: {e}") from e

    return processed

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # Validate the input type
    if not isinstance(tag, str):
        return False

    # Strip leading/trailing whitespace
    tag = tag.strip()
    if not tag:
        return False

    # Define a pattern: start with letter or digit, followed by letters, digits, underscores or hyphens
    import re
    pattern = re.compile(r'^[A-Za-z0-9][A-Za-z0-9_-]*$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # Wrap node in list if it's an ElementTree root to iterate its children
    try:
        children = list(node)
    except TypeError:
        raise TypeError("Provided node must support iteration over its children (e.g., an ElementTree element).")
    result = {}
    for child in children:
        tag = str(child.tag)
        # If we already have this tag, create a list of children for that tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if not isinstance(sender_handle, str):
        raise TypeError(f"sender_handle must be str, got {type(sender_handle).__name__}")
    if not isinstance(entity_handle, str):
        raise TypeError(f"entity_handle must be str, got {type(entity_handle).__name__}")
    if sender_handle != entity_handle:
        raise ValueError(f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'.")
    return True

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate input
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    # Remove any trailing slash for consistency
    base = url.rstrip('/')
    # Determine the .well-known path
    if document_path is None:
        # Default NodeInfo document location as per spec
        path = f"{base}/.well-known/nodeinfo"
    else:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string if provided")
        # Ensure that the path starts with a slash if not absolute
        if not document_path.startswith('/'):
            document_path = '/' + document_path
        path = base + document_path

    # Build a minimal NodeInfo document
    node_info = {
        "nodes": [
            {
                "protocols": ["activitypub", "diaspora"],
                "software": {"name": "example-node", "version": "1.0"},
                "links": [
                    {
                        "rel": "self",
                        "type": "application/json",
                        "href": f"{base}/nodeinfo/2.0"
                    }
                ],
                "openRegistrations": False,
                "updateDue": 0,
                "lastUpdated": None,
                "metadata": {}
            }
        ],
        "website": base,
        "software": {"name": "example-node-software", "version": "1.0"},
        "protocols": ["activitypub", "diaspora"],
        "openRegistrations": False,
        "updateDue": 0,
        "lastUpdated": None,
        "metadata": {}
    }

    return node_info

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not document:
        return {}

    data = document.lstrip()
    if data[0] in ("{", "["):
        try:
            return json.loads(data)
        except json.JSONDecodeError as exc:
            raise ValueError("Invalid JSON webfinger document") from exc

    # Assume XML (XRD)
    try:
        root = ET.fromstring(data)
    except ET.ParseError as exc:
        raise ValueError("Invalid XRD webfinger document") from exc

    # Helper to strip namespace
    def _strip(tag: str) -> str:
        return tag.split("}")[-1] if "}" in tag else tag

    def _findtext(elem, tag):
        return elem.findtext(tag) or elem.findtext(f".//{{*}}{tag}")

    subject = _findtext(root, "Subject")
    if subject is None:
        subject = _findtext(root, "subject")

    aliases = [a.text for a in root.findall("Alias")]
    if not aliases:
        aliases = [a.text for a in root.findall(".//{*}Alias")]

    links = []
    for link in root.findall("Link"):
        links.append(link.attrib)
    if not links:
        # fallback with namespace searching
        for link in root.findall(".//{*}Link"):
            links.append(link.attrib)

    return {
        "subject": subject,
        "aliases": aliases,
        "links": links,
    }

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        handle = handle.strip()
        if '@' not in handle:
            return None
        domain = handle.split('@', 1)[1]
        url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
        import urllib.request
        with urllib.request.urlopen(url, timeout=5) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except Exception:
        return None

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    import ssl
    import xml.etree.ElementTree as ET

    # Normalize host to just hostname (strip scheme if present)
    if host.startswith("http://"):
        host = host[len("http://") :]
    elif host.startswith("https://"):
        host = host[len("https://") :]

    # Construct the URL; attempt HTTPS first
    base_url = f"https://{host}/.well-known/host-meta"

    # Helper to fetch from a given URL
    def _fetch(url):
        context = ssl.create_default_context()
        with urllib.request.urlopen(url, context=context, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(
                    f"Failed to retrieve host-meta from {host}: HTTP {resp.status}"
                )
            return resp.read()

    # Try HTTPS, fall back to HTTP if SSL errors occur
    try:
        data = _fetch(base_url)
    except (urllib.error.URLError, ssl.SSLError):
        # Try plain HTTP
        try:
            data = _fetch(f"http://{host}/.well-known/host-meta")
        except urllib.error.HTTPError as e:
            raise RuntimeError(
                f"HTTP error retrieving host-meta from {host}: {e}"
            ) from e
        except urllib.error.URLError as e:
            raise RuntimeError(
                f"URL error retrieving host-meta from {host}: {e}"
            ) from e

    # Parse the XML into an ElementTree element
    try:
        root = ET.fromstring(data)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse host-meta XML from {host}") from e

    # Some libraries expect an XRD class instance; if such exists we
    # wrap the ElementTree element accordingly, otherwise return the
    # ElementTree root directly.
    try:
        from xrd import XRD  # type: ignore
        return XRD(root)
    except Exception:  # pragma: no cover
        return root

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    import warnings

    # Validate input types
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths")
    if spec_option is not None and not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string or None")

    file_names = []

    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            warnings.warn(f"Directory path {dir_path!r} is not a string, skipping.")
            continue

        if not os.path.isdir(dir_path):
            warnings.warn(f"Directory {dir_path!r} does not exist, skipping.")
            continue

        for root, _, files in os.walk(dir_path):
            for filename in files:
                if spec_option:
                    # Support simple patterns like '*.ini' or specific extensions like '.ini'
                    if fnmatch.fnmatch(filename, spec_option) or filename.endswith(spec_option):
                        file_names.append(os.path.join(root, filename))
                else:
                    file_names.append(os.path.join(root, filename))

    return file_names

def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    # Cache the manager on the class so we only import once
    if not hasattr(cls, "_ansible_config_manager"):
        try:
            from ansible import constants as C
            cls._ansible_config_manager = C
        except Exception as exc:
            raise RuntimeError(
                "Unable to import Ansible configuration constants. "
                "Make sure Ansible is installed and available in the environment."
            ) from exc
    return cls._ansible_config_manager

