def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # Load YAML if the input is a string, otherwise assume it is already a dictionary
    if isinstance(spec_content, str):
        try:
            import yaml
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Unable to parse YAML content: {exc}") from exc
    elif isinstance(spec_content, dict):
        data = spec_content
    else:
        raise IRValidatorException(f"Unsupported spec_content type: {type(spec_content)}")

    # Ensure the parsed data is a dictionary
    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must parse to a dictionary")

    # Retrieve required fields from the class if defined
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(
            f"Missing required fields in spec: {', '.join(missing)}"
        )

    return data

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file specified")

        try:
            import yaml
        except ImportError:
            raise IRValidatorException("PyYAML is required to load YAML files")

        try:
            with open(yaml_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError:
            raise IRValidatorException(f"YAML file not found: {yaml_file}")
        except yaml.YAMLError as exc:
            raise IRValidatorException(f"Error parsing YAML file: {exc}")

        if data is None:
            raise IRValidatorException("YAML file contains no data")
        if not isinstance(data, dict):
            raise IRValidatorException("YAML root must be a mapping (dict)")

        required = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in YAML: {', '.join(missing)}")

        return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec = getattr(self, "spec", None)
    if not isinstance(spec, dict):
        # No spec available or not a dict – nothing to resolve
        return defaults
    try:
        for key, props in spec.items():
            if not isinstance(props, dict):
                continue
            # Store the default if defined
            if "default" in props:
                # Only set the attribute if it hasn't been set yet
                if getattr(self, key, None) is None:
                    setattr(self, key, props["default"])
                defaults[key] = getattr(self, key)
    except Exception as e:
        # Catch unexpected errors from spec processing
        raise ValueError(
            f"Failed to resolve defaults from spec: {e}"
        ) from e
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    # By default, there are no deprecated arguments.
    return {}

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if command_name == "":
        raise ValueError("command_name cannot be empty")

    # The mapping that stores option specs; fallback to empty dict if attribute missing
    option_map = getattr(self, "_parser_option_specs", None)
    if option_map is None:
        option_map = getattr(self, "parser_option_specs", {})
    if not isinstance(option_map, dict):
        raise AttributeError("Expected a dictionary of parser options, got %r" % (type(option_map),))

    # Retrieve options for the given command
    opts = option_map.get(command_name, [])

    # Normalise to a list and return a shallow copy to prevent accidental mutation
    if isinstance(opts, list):
        return opts.copy()
    try:
        return list(opts)
    except TypeError:
        # Non-iterable value; wrap it in a list
        return [opts]

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str) or not command_name:
        raise TypeError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise TypeError("argument_name must be a non-empty string")

    # Determine where the command specifications are stored
    if hasattr(self, "command_specs"):
        cmd_map = self.command_specs
    elif hasattr(self, "commands"):
        cmd_map = self.commands
    else:
        raise AttributeError(
            "Could not find a command specification structure on this object"
        )

    # Find the specified command
    command_spec = cmd_map.get(command_name)
    if command_spec is None:
        # Try treating cmd_map as a mapping from command objects to specs
        for key, value in dict(cmd_map).items():
            if getattr(key, "name", None) == command_name:
                command_spec = value
                break
    if command_spec is None:
        raise ValueError(f"Command '{command_name}' not found")

    # Locate the options dictionary for the command
    options = None
    if isinstance(command_spec, dict):
        options = command_spec.get("options") or command_spec.get("args") or command_spec.get("parameters")
    else:
        options = getattr(command_spec, "options", None) or getattr(command_spec, "args", None) or getattr(command_spec, "parameters", None)

    if options is None:
        raise ValueError(f"Command '{command_name}' does not contain an options mapping")

    # Retrieve the specification for the requested option
    option_spec = options.get(argument_name)
    if option_spec is None:
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'")

    return option_spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    if args is None:
        return silent
    # If args is a mapping, consider a silenced argument where the value is `None` or `False`
    if isinstance(args, dict):
        try:
            for key, value in args.items():
                if value in (None, False):
                    silent.append(key)
        except Exception:
            # If something goes wrong with dict iteration, return what we have so far
            return silent
    # If args is an iterable of strings (but not a dict), we cannot determine silenced status
    # without further context; thus we return an empty list.
    elif isinstance(args, (list, tuple, set)):
        # Safely ensure all elements are convertible to strings
        try:
            for item in args:
                if not isinstance(item, str):
                    continue
                # No criteria available to mark as silent, ignore.
                pass
        except Exception:
            # In case of unexpected errors, return empty list
            return silent
    else:
        # Unsupported type; return empty list
        return silent
    return silent

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        if options_spec is None:
            return []
        # Ensure args is a mapping for lookup
        if not isinstance(args, dict):
            try:
                args = dict(args)
            except Exception:
                args = {}
        required = []
        for opt in options_spec:
            # option name could be stored under different keys
            name = opt.get("name") or opt.get("opt") or opt.get("id") or opt.get("arg")
            if not name:
                continue
            req_when = opt.get("required_when")
            if not req_when:
                continue
            satisfied = False
            try:
                if callable(req_when):
                    # pass command_name and args
                    satisfied = bool(req_when(command_name=command_name, args=args))
                elif isinstance(req_when, str):
                    # eval expression with limited globals
                    satisfied = bool(eval(req_when, {}, {"command_name": command_name, "args": args}))
                elif isinstance(req_when, dict):
                    # all key/value pairs must match exactly
                    satisfied = all(args.get(k) == v for k, v in req_when.items())
                elif isinstance(req_when, (list, tuple)):
                    # treat list/tuple as a group of conditions that all must be true
                    # each element may be a callable, string, or dict
                    conds = []
                    for c in req_when:
                        if callable(c):
                            conds.append(c(command_name=command_name, args=args))
                        elif isinstance(c, str):
                            conds.append(eval(c, {}, {"command_name": command_name, "args": args}))
                        elif isinstance(c, dict):
                            conds.append(all(args.get(k) == v for k, v in c.items()))
                        else:
                            conds.append(False)
                    satisfied = all(conds)
                else:
                    # Unsupported type; treat as not satisfied
                    satisfied = False
            except Exception:
                # If any error occurs (e.g., eval error), treat as not satisfied
                satisfied = False
            if satisfied:
                required.append(name)
        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    # Retrieve a mapping of argument names to max lengths, if available
    max_lengths = getattr(self, "max_lengths", {})
    for name, value in args.items():
        # Skip if no length constraint defined for this argument
        limit = max_lengths.get(name)
        if limit is None:
            continue
        if value is None:
            continue
        # Only enforce length on string values
        if isinstance(value, str) and len(value) > limit:
            raise ValueError(
                f"Argument '{name}' exceeds maximum length of {limit} characters "
                f"(actual length: {len(value)})"
            )
    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure ``args`` is a mapping
    if not isinstance(args, dict):
        raise TypeError("`args` must be a dict mapping argument names to values")

    # If the class does not define any choices, nothing to validate
    if not hasattr(self, "choices"):
        return

    choices = getattr(self, "choices")
    if not isinstance(choices, dict):
        raise ValueError("`self.choices` must be a dict mapping argument names to allowed values")

    for name, value in args.items():
        # Only validate keys that have a defined list of choices
        if name not in choices:
            continue

        allowed = choices[name]
        # Normalize allowed to an iterable
        if not isinstance(allowed, (list, tuple, set)):
            allowed = [allowed]

        # Allow None or empty values to bypass validation
        if value is None or value == "":
            continue

        # If the provided value is a collection (e.g., list/tuple) interpret it as a multi-select
        if isinstance(value, (list, tuple)):
            invalid = [v for v in value if v not in allowed]
            if invalid:
                raise ValueError(
                    f"Invalid values for argument '{name}': {invalid}. "
                    f"Expected values to be subset of {allowed}."
                )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value!r}. "
                    f"Expected one of {allowed}."
                )

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        if args is None:
            raise TypeError("Argument 'args' must not be None")
        try:
            iterator = iter(args)
        except TypeError:
            raise TypeError("Argument 'args' must be an iterable of values")

        # Minimum and maximum values may be defined as attributes of the instance.
        min_val = getattr(self, "min_value", None)
        max_val = getattr(self, "max_value", None)

        for arg in iterator:
            if arg is None:
                continue
            if not isinstance(arg, (int, float)):
                raise TypeError(f"Argument value {arg!r} must be numeric")
            if (min_val is not None) and (arg < min_val):
                raise ValueError(
                    f"Argument {arg!r} less than minimum allowed {min_val!r}"
                )
            if (max_val is not None) and (arg > max_val):
                raise ValueError(
                    f"Argument {arg!r} greater than maximum allowed {max_val!r}"
                )
        return True

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if args is None:
        return {}, {}

    # Accept either a dict or a list/tuple of key/value pairs
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        # Expect alternating key/value pairs
        if len(args) % 2 != 0:
            raise ValueError("args list must contain an even number of elements (key/value pairs).")
        items = ((args[i], args[i + 1]) for i in range(0, len(args), 2))
    else:
        raise TypeError(f"Unsupported type for args: {type(args).__name__}")

    control_args = {}
    nested_args = {}
    # Define control keys – extend this set if needed
    CONTROL_KEY_PREFIXES = ('_', 'control_', 'ignore_', 'debug_')
    CONTROL_STRINGS = set(['dryrun', 'verbose', 'debug', 'quiet'])

    for key, value in items:
        # Normalize key to string for checking
        try:
            k_str = str(key).lower()
        except Exception:
            k_str = ''
        # Determine category
        if any(k_str.startswith(p) for p in CONTROL_KEY_PREFIXES) or k_str in CONTROL_STRINGS or key.startswith('--'):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict

    # Prepare a dictionary of extra vars to merge
    extra_dict = {}
    try:
        if isinstance(extra_vars, dict):
            extra_dict = dict(extra_vars)
        elif isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                if isinstance(item, dict):
                    extra_dict.update(item)
                elif isinstance(item, str) and "=" in item:
                    key, value = item.split("=", 1)
                    extra_dict[key.strip()] = value.strip()
                # ignore unexpected formats
    except Exception:
        # If anything goes wrong, just leave vars_dict unchanged
        return vars_dict

    if not extra_dict:
        return vars_dict

    # Merge into the base dict under the key 'extra-vars'
    if "extra-vars" in vars_dict:
        base = vars_dict["extra-vars"]
        if isinstance(base, dict):
            base.update(extra_dict)
        else:
            vars_dict["extra-vars"] = extra_dict
    else:
        vars_dict["extra-vars"] = extra_dict

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict parameter.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dictionary of arguments
    """
    # Resolve any predefined type mapping for this parser
    types_map = {}
    try:
        # Expecting an attribute like `self.arg_types` to hold type info
        types_map = getattr(self, 'arg_types', {}).get(parser_name, {})
    except Exception:
        # If any issue occurs, fall back to heuristic conversion
        types_map = {}

    # Iterate over a copy of keys to allow mutation
    for key, val in list(values_dict.items()):
        if val is None:
            continue

        # Attempt explicit conversion based on defined mapping
        target_type = types_map.get(key)
        if target_type:
            try:
                # Handle special case for bool conversion via target_type
                if target_type is bool:
                    values_dict[key] = bool(val)
                else:
                    values_dict[key] = target_type(val)
                continue
            except Exception:
                pass  # fall back to heuristic conversion

        # Heuristic conversion only for string values
        if not isinstance(val, str):
            continue

        raw = val.strip()
        if raw == '':
            values_dict[key] = None
            continue

        lowered = raw.lower()
        # Boolean
        if lowered in ('true', 'false', 'yes', 'no', '1', '0', 'on', 'off'):
            values_dict[key] = lowered in ('true', 'yes', '1', 'on')
            continue

        # Integer
        try:
            if '.' not in raw:
                values_dict[key] = int(raw)
                continue
        except ValueError:
            pass

        # Float
        try:
            values_dict[key] = float(raw)
            continue
        except ValueError:
            pass

        # List (comma separated)
        if ',' in raw:
            try:
                values_dict[key] = [item.strip() for item in raw.split(',')]
                continue
            except Exception:
                pass

        # Fallback: keep as string
        values_dict[key] = raw

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Validate plugin_dir
    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory does not exist: {plugin_dir}")

    # Find spec file
    spec_file = None
    for fname in ('plugin.json', 'plugin.yaml', 'plugin.yml', 'spec.json', 'spec.yaml', 'spec.yml'):
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_file = potential
            break

    if not spec_file:
        # No spec file found, return empty dict
        return {}

    # Load spec
    spec_data = {}
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                spec_data = json.load(f)
            else:
                try:
                    import yaml
                    spec_data = yaml.safe_load(f)
                except Exception as e:
                    # If yaml import fails or parsing fails, treat as empty
                    spec_data = {}
    except Exception as e:
        # Any error reading or parsing fallback to empty dict
        spec_data = {}

    # If not a dict, cannot flatten
    if not isinstance(spec_data, dict):
        return {}

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os

    env_var = "CONFIG_PATH"
    if env_var in os.environ:
        return

    default_path = None
    if hasattr(self, "config_path"):
        default_path = getattr(self, "config_path")
    elif hasattr(self, "path"):
        default_path = getattr(self, "path")

    if default_path is None:
        default_path = os.path.join(os.getcwd(), "config.yaml")

    os.environ[env_var] = str(default_path)
